# Now verify chromatic number is EXACTLY 3 (not 2)
# Check if the found graph is 2-colorable (bipartite)
# If it's bipartite, chromatic number <= 2, which violates >= 3

def is_bipartite(vertices, adj):
    color = {}
    for start in vertices:
        if start in color:
            continue
        queue = [start]
        color[start] = 0
        while queue:
            node = queue.pop()
            for nb in adj.get(node, []):
                if nb not in color:
                    color[nb] = 1 - color[node]
                    queue.append(nb)
                elif color[nb] == color[node]:
                    return False
    return True

def check_graph(edges):
    adj = {v: [] for v in range(8)}
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    bip = is_bipartite(list(range(8)), adj)
    print(f"Is bipartite (2-colorable): {bip}")

    # Count edges
    print(f"Edge count: {len(edges)}")

    # Check degrees
    for v in range(8):
        deg = len(adj[v])
        print(f"  Vertex {v}: degree {deg}")

    return bip

